#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846

int main(void) {
    int n;
    double l;
    scanf("%d %lf", &n, &l);
    double area = (n * l * l / 4.0) * (cos(PI/n) / sin(PI/n));
    printf("%.4f\n", area);
    return 0;
}

#include <stdio.h>

int main(void) {
    double a, b, c;
    scanf("%lf %lf %lf", &a, &b, &c);
    double xv = -b / (2.0 * a);
    double yv = c - b*b / (4.0*a);
    printf("%.4f\n%.4f\n", xv, yv);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double x1, y1, x2, y2, x3, y3;
    scanf("%lf %lf %lf %lf %lf %lf", &x1, &y1, &x2, &y2, &x3, &y3);
    double area = fabs(x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2)) / 2.0;
    printf("%.3f\n", area);
    return 0;
}

#include <stdio.h>

int main(void) {
    double capital, inflacao;
    int anos;
    scanf("%lf %lf %d", &capital, &inflacao, &anos);
    double poder = capital;
    for(int i=0; i<anos; i++) {
        poder = poder / (1.0 + inflacao / 100.0);
    }
    printf("%.2f\n", poder);
    return 0;
}

#include <stdio.h>

int main(void) {
    double a1, r;
    scanf("%lf %lf", &a1, &r);
    double a60 = a1 + (60 - 1) * r;
    printf("%.2f\n", a60);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double a, t;
    scanf("%lf %lf", &a, &t);
    double s = 0.5 * a * t * t;
    double v = a * t;
    printf("%.2f\n%.2f\n", s, v);
    return 0;
}

#include <stdio.h>

int main(void) {
    double valor, taxa;
    int dias;
    scanf("%lf %lf %d", &valor, &taxa, &dias);
    double atual = valor * (1.0 - (taxa / 100.0) * dias);
    printf("%.2f\n", atual);
    return 0;
}

#include <stdio.h>

int main(void) {
    double largura, comprimento, custo_m2;
    scanf("%lf %lf %lf", &largura, &comprimento, &custo_m2);
    double area = largura * comprimento;
    double area_com_perda = area * 1.10;
    double custo_total = area_com_perda * custo_m2;
    printf("%.2f\n%.2f\n", area_com_perda, custo_total);
    return 0;
}
